import{s as e}from"./hitbox.js";import{x as t}from"./shareTexts.js";import{t as n}from"./SharePill.js";var r=e(),i={fontSize:11,color:`var(--text-faint)`,lineHeight:1.5,textAlign:`left`};function a({share:e,setShare:a,shortProps:o,fullProps:s,shortHint:c,shortLabel:l,fullLabel:u,zIndex:d}){return!o&&!s?null:(0,r.jsxs)(r.Fragment,{children:[o&&(0,r.jsxs)(`div`,{style:{marginTop:8},children:[(0,r.jsx)(n,{label:l??`Поделиться карточкой`,onClick:()=>a(`short`)}),(0,r.jsx)(`div`,{style:{...i,marginTop:6},children:c})]}),s&&(0,r.jsxs)(`div`,{style:{marginTop:o?12:8},children:[(0,r.jsx)(n,{label:u,onClick:()=>a(`full`)}),s.hint&&(0,r.jsx)(`div`,{style:{...i,marginTop:6},children:s.hint})]}),e===`short`&&o&&(0,r.jsx)(t,{...o,zIndex:d,onClose:()=>a(null)}),e===`full`&&s&&(0,r.jsx)(t,{...s,zIndex:d,onClose:()=>a(null)})]})}var o={vulnerable_child:{about:`Базовый режим детской боли — не защита и не поведение, а само чувство: беспомощность, грусть, страх, ощущение брошенности.`,triggers:`Отвержение; критика; одиночество; отсутствие опоры и поддержки рядом.`,body:`Ком в горле, слёзы, сжатие в груди, желание свернуться и спрятаться.`,voice:`«Мне плохо, и разделить это не с кем»`,behavior:`Замирает, плачет, ищет утешения или молча уходит в себя.`,origin:`Живая, естественная реакция ребёнка на боль, которую когда-то было некому разделить.`,cost:`Без опоры извне и изнутри ощущается невыносимым — включает защитные режимы, чтобы заглушить его.`,need:`Безопасность, тепло, присутствие рядом, право на утешение без стыда.`,healthyAdult:`«Мне сейчас больно, и это по-настоящему. Я рядом с собой — можно не справляться в одиночку»`},lonely_child:{about:`Ощущение одиночества и непонятости даже в кругу людей — будто настоящий контакт недоступен.`,triggers:`Быть среди людей без ощущения близости; чувство, что никто не видит по-настоящему.`,body:`Пустота внутри, тяжесть в груди, ощущение стекла между собой и другими.`,voice:`«Никто меня по-настоящему не видит»`,behavior:`Физически рядом с людьми, но эмоционально отстранён; молчит о главном.`,origin:`Возник там, где эмоциональная близость была недоступна, даже когда людей рядом хватало.`,cost:`Мешает просить и принимать поддержку — одиночество усиливается вместо того, чтобы проходить.`,need:`Настоящий контакт — чтобы увидели и поняли того, кто внутри.`,healthyAdult:`«Одиночество внутри — это чувство, а не факт. Можно позволить кому-то подойти ближе»`},abandoned_child:{about:`Страх, что бросят — острая тревога, что близкий человек уйдёт или окажется ненадёжным.`,triggers:`Молчание в переписке; отдаление близкого человека; любой намёк на расставание.`,body:`Учащённое сердцебиение, паника, желание немедленно вернуть контакт.`,voice:`«Сейчас меня оставят — и всё»`,behavior:`Проверяет, звонит, требует подтверждений или, наоборот, уходит первым на опережение.`,origin:`Сформировался там, где близкие люди действительно были непредсказуемы или исчезали.`,cost:`Тревога о будущей потере мешает быть в настоящем — отношения проверяются, а не проживаются.`,need:`Устойчивость и надёжность связи, уверенность, что отношения выдержат дистанцию.`,healthyAdult:`«Тишина — не всегда уход. Можно заметить тревогу и не спешить с выводами»`},humiliated_child:{about:`Стыд и ощущение внутренней дефективности — будто, узнав правду, все отвернутся.`,triggers:`Критика; разоблачение слабости; риск, что заметят несовершенство.`,body:`Жар в лице, желание сжаться, съёжиться, исчезнуть из виду.`,voice:`«Со мной что-то не так»`,behavior:`Избегает взглядов, оправдывается, прячет то, что кажется постыдным.`,origin:`Возник там, где детей стыдили или высмеивали за то, какие они есть.`,cost:`Прячет свою подлинность — а близость и принятие невозможны без открытости.`,need:`Принятие таким, какой есть, без условия «сначала стань лучше».`,healthyAdult:`«Стыд — не факт обо мне. Могу открыться по-настоящему и остаться в безопасности»`},dependent_child:{about:`Ощущение неспособности справиться самостоятельно — страх принимать решения без чужой опоры.`,triggers:`Необходимость решить важное в одиночку; ответственность без подсказки со стороны.`,body:`Растерянность, слабость в теле, желание переложить выбор на кого-то другого.`,voice:`«В одиночку не справлюсь»`,behavior:`Откладывает решение, спрашивает совета у всех подряд, ждёт, что решение примут другие.`,origin:`Сложился там, где самостоятельность не поощрялась или наказывалась ошибками.`,cost:`Компетентность не накапливается — каждое решение снова кажется непосильным.`,need:`Опыт того, что маленький самостоятельный шаг безопасен и получается.`,healthyAdult:`«Можно попробовать один маленький шаг своими силами — не идеально, и этого достаточно»`},angry_child:{about:`Злость как естественный ответ на нарушенные потребности или несправедливость.`,triggers:`Игнорирование потребностей; нарушенные границы; явная несправедливость.`,body:`Жар, напряжение в челюсти и кулаках, учащённое дыхание.`,voice:`«Это несправедливо»`,behavior:`Повышает голос, спорит, хлопает дверью, резко отстаивает своё.`,origin:`Естественная реакция ребёнка, которому не давали защищать свои потребности словами.`,cost:`Пугает окружающих и включает вину или критику в ответ — злость остаётся невыраженной.`,need:`Право злиться — и чтобы это услышали, не наказывая за чувство.`,healthyAdult:`«Моя злость — сигнал, что нарушено что-то важное. Можно сказать об этом словами»`},stubborn_child:{about:`Упрямое сопротивление любому давлению, требованию или контролю извне.`,triggers:`Приказы и навязанные правила; ощущение, что решение отнимают силой.`,body:`Напряжение во всём теле, стиснутые зубы, внутреннее «нет».`,voice:`«Не буду — и всё»`,behavior:`Саботирует, тянет время, отказывает даже во вред себе.`,origin:`Появился там, где единственным способом сохранить автономию был отказ.`,cost:`Сопротивление ради сопротивления вредит собственным же целям и отношениям.`,need:`Ощущение выбора и уважение к собственному «нет», а не борьба за него.`,healthyAdult:`«Моё мнение важно и без борьбы. Можно выбрать своё, не воюя»`},enraged_child:{about:`Неконтролируемая ярость, поднимающаяся волной и почти не поддающаяся сдерживанию.`,triggers:`Сильная угроза; накопленная несправедливость; ощущение полного бессилия.`,body:`Дрожь, жар по всему телу, тоннельное зрение, готовность взорваться.`,voice:`«Меня сейчас разнесёт»`,behavior:`Кричит, крушит, может ударить или сказать то, о чём потом жалеет.`,origin:`Копилась там, где злость долго не находила выхода и накапливалась внутри.`,cost:`Пугает окружающих и самого человека, разрушает отношения и доверие к себе.`,need:`Безопасный выход для накопленной злости раньше, чем она достигнет пика.`,healthyAdult:`«Ярость — сигнал перегрузки. Можно сделать паузу и выдохнуть, прежде чем действовать»`},impulsive_child:{about:`Действует по первому желанию, не успевая подумать о последствиях.`,triggers:`Сильное сиюминутное желание; скука; невозможность вытерпеть ожидание.`,body:`Возбуждение, нетерпение, тело будто само тянется к действию.`,voice:`«Хочу это прямо сейчас»`,behavior:`Хватает, тратит, говорит первое, что пришло, не оценивая последствий.`,origin:`Возник там, где немедленное удовлетворение было единственной доступной радостью.`,cost:`Импульсивные решения потом приходится расхлёбывать — деньгами, отношениями, доверием.`,need:`Опыт того, что желание можно назвать и отложить, не потеряв его совсем.`,healthyAdult:`«Желание можно заметить и не спешить с ним. Оно никуда не денется за минуту паузы»`},undisciplined_child:{about:`Теряет интерес и бросает начатое, как только становится скучно или трудно.`,triggers:`Рутина; монотонная задача; усилие без немедленного результата.`,body:`Вялость, рассеянность, тяжесть в теле при мысли о продолжении.`,voice:`«Скучно, не хочу это доделывать»`,behavior:`Откладывает, переключается на другое, бросает задачу на полпути.`,origin:`Сложился там, где скука и усилие никогда не вели к интересному результату.`,cost:`Незавершённые дела копятся, компетентность и уверенность в себе не растут.`,need:`Опыт, что через скуку можно пройти и получить результат, которым можно гордиться.`,healthyAdult:`«Скука — это просто скука, не сигнал остановиться. Ещё немного — и будет результат»`}},s={compliant_surrenderer:{about:`Соглашается со всем и подстраивается, лишь бы избежать конфликта или отвержения.`,triggers:`Любой намёк на несогласие; конфликт; риск не понравиться или разочаровать.`,body:`Напряжение под фальшивой улыбкой, сжатое горло на невысказанном «нет».`,voice:`«Да, конечно, как скажете»`,behavior:`Соглашается, подстраивается, глотает собственное мнение и желания.`,origin:`Появился там, где несогласие каралось или разрывало отношения.`,cost:`Собственные желания копятся невысказанными, накапливаются скрытая обида и усталость.`,need:`Опыт того, что «нет» можно сказать и отношения от этого не разрушатся.`,healthyAdult:`«Мои желания и границы тоже важны. Даже маленькое "нет" — уже забота о себе»`},helpless_surrenderer:{about:`Ощущение полного бессилия перед ситуацией — проще сдаться, чем пытаться повлиять.`,triggers:`Сложная задача; ощущение, что от собственных усилий ничего не зависит.`,body:`Тяжесть, апатия, опущенные плечи, желание просто перестать пытаться.`,voice:`«Всё равно ничего не изменить»`,behavior:`Опускает руки, ждёт, что ситуацию решат другие, перестаёт пробовать.`,origin:`Сложился там, где попытки повлиять раз за разом не давали результата.`,cost:`Реальные возможности повлиять на ситуацию упускаются вместе с верой в себя.`,need:`Опыт маленького реального влияния — что усилие всё же что-то меняет.`,healthyAdult:`«Не всё в моих руках, но что-то — да. Можно попробовать один маленький шаг»`},detached_protector:{about:`Отключает чувства целиком, чтобы боль стала незаметной — внутри пусто и плоско.`,triggers:`Ситуация, грозящая задеть слишком сильно; накопленная эмоциональная перегрузка.`,body:`Онемение, туман в голове, ощущение отдалённости от собственного тела.`,voice:`«Нужно, чтобы меня сейчас не трогали»`,behavior:`Уходит в себя, отвечает односложно, избегает любого эмоционального контакта.`,origin:`Возник как защита там, где чувствовать было слишком больно и небезопасно.`,cost:`Блокирует не только боль, но и радость, близость, живой контакт с собой и другими.`,need:`Ощущение безопасности, достаточной для того, чтобы постепенно вернуться к чувствам.`,healthyAdult:`«Броня стоит, чтобы не было больно — это понятно. Сейчас безопасно, можно понемногу приоткрыться»`},detached_self_soother:{about:`Заглушает внутреннюю пустоту через еду, экраны, покупки или другие привычки.`,triggers:`Скука; тревога; эмоциональная пустота; момент наедине с собой.`,body:`Автоматическая тяга к действию, лёгкое облегчение сразу и пустота после.`,voice:`«Ещё немного — и станет полегче»`,behavior:`Листает ленту, ест не от голода, включает сериал, лишь бы не оставаться с чувством.`,origin:`Появился там, где утешение и присутствие рядом было недоступно, и пришлось найти замену.`,cost:`Отвлечение глушит чувство на время, но не даёт с ним по-настоящему встретиться.`,need:`Настоящее утешение и присутствие — не заменитель, а живой контакт с собой или другим.`,healthyAdult:`«Можно на минуту остаться с тем, что внутри, а не сразу убегать в отвлечение»`},avoidant_protector:{about:`Обходит стороной ситуации, людей и дела, которые могут задеть или причинить боль.`,triggers:`Задача или разговор, вызывающие тревогу; риск столкнуться с болезненным чувством.`,body:`Тревога при одной мысли о ситуации, облегчение сразу после того, как удалось её обойти.`,voice:`«Лучше вообще туда не соваться»`,behavior:`Откладывает, находит причины не пойти, физически уходит из ситуации.`,origin:`Сложился там, где столкновение с трудностью раз за разом заканчивалось болью.`,cost:`Тревога не проходит, а только укрепляется — то, чего избегают, кажется всё страшнее.`,need:`Опыт маленького безопасного столкновения с тем, что обходится, — тревога от этого снижается.`,healthyAdult:`«Маленький шаг навстречу тому, чего избегаю, меняет больше, чем очередной обход»`},angry_protector:{about:`Держит людей на расстоянии раздражением и колючестью, защищая уязвимое внутри.`,triggers:`Приближение к болезненной теме; попытка кого-то подойти слишком близко.`,body:`Напряжение, раздражение на грани срыва, желание огрызнуться или отгородиться.`,voice:`«Лучше держаться от меня подальше»`,behavior:`Огрызается, саркастичен, отталкивает близких людей злостью.`,origin:`Появился там, где близость когда-то оборачивалась болью, и злость стала щитом.`,cost:`Отталкивает именно тех, чья поддержка сейчас действительно нужна.`,need:`Ощущение безопасности рядом с другими настолько, чтобы щит стало можно снять.`,healthyAdult:`«Злюсь не столько на людей, сколько чтобы не дотянулись до больного. Можно приопустить щит»`}},c={self_aggrandiser:{about:`Ощущение особости и превосходства над другими — способ не проваливаться в ничтожность.`,triggers:`Ситуации сравнения; риск обычности и недостаточной значимости.`,body:`Подъём, напряжённая гордость, раздражение при сомнении в своей исключительности.`,voice:`«Я лучше и особеннее большинства»`,behavior:`Хвастается, смотрит свысока, обесценивает чужие достижения.`,origin:`Возник там, где обычность означала незаметность и недостаточность.`,cost:`Изматывает необходимостью постоянно доказывать превосходство, отдаляет от людей.`,need:`Ощущение собственной ценности без сравнения и превосходства над кем-то.`,healthyAdult:`«Мне не нужно быть выше других, чтобы что-то значить. Обычность и живость — это нормально»`},overcontroller:{about:`Стремится держать под контролем максимум происходящего, чтобы не случилось непредсказуемого.`,triggers:`Неопределённость; ситуация вне прямого контроля; чужие решения, влияющие на него.`,body:`Напряжение, невозможность расслабиться, пока не проверено и не спланировано всё.`,voice:`«Если не проконтролирую — случится плохое»`,behavior:`Планирует, перепроверяет, вмешивается в чужие задачи, с трудом делегирует.`,origin:`Сложился там, где непредсказуемость окружения когда-то была настоящей угрозой.`,cost:`Истощает силы и раздражает окружающих; полностью предсказуемого не бывает.`,need:`Опыт того, что часть неопределённости можно выдержать без потери безопасности.`,healthyAdult:`«Не всё мне подвластно — и это выносимо. Можно ослабить хватку и выдохнуть»`},perfectionistic_oc:{about:`Держит недостижимо высокую планку — сделанное никогда не кажется достаточно хорошим.`,triggers:`Задача с оценкой результата; риск показать несовершенную работу.`,body:`Напряжение в теле, невозможность остановиться, пока не переделано ещё раз.`,voice:`«Ещё не идеально, надо переделать»`,behavior:`Многократно проверяет, переделывает, откладывает сдачу результата.`,origin:`Появился там, где ценность признавалась только за безупречный результат.`,cost:`Покой не наступает никогда, а страх ошибки перевешивает радость от сделанного.`,need:`Опыт того, что достаточно хорошо — уже достаточно, и это не наказуемо.`,healthyAdult:`«Сделано — уже хорошо. Можно остановиться, не дожидаясь идеала, которого не существует»`},suspicious_oc:{about:`Постоянно настороже, ищет скрытые мотивы и подвох там, где их может и не быть.`,triggers:`Новые люди; неясные намерения других; ситуации без полной информации.`,body:`Напряжённая бдительность, недоверчивость, трудно расслабиться рядом с людьми.`,voice:`«Тут явно что-то не так, надо быть начеку»`,behavior:`Перепроверяет слова людей, держит дистанцию, ищет двойное дно в простых фразах.`,origin:`Сложился там, где доверие однажды было использовано во вред.`,cost:`Мешает близости — даже безопасные люди воспринимаются как потенциальная угроза.`,need:`Опыт того, что довериться понемногу — не то же самое, что довериться слепо.`,healthyAdult:`«Не каждый — угроза. Можно проверять постепенно, а не отказываться от доверия совсем»`},invincible_oc:{about:`Отрицает любую слабость — справляться приходится при любых обстоятельствах в одиночку.`,triggers:`Ситуация, где нужна помощь; боль или усталость, которую «не положено» показывать.`,body:`Стиснутая челюсть, подавленная усталость, отказ замечать собственное истощение.`,voice:`«Справлюсь в одиночку, помощь не нужна»`,behavior:`Отказывается от поддержки, скрывает трудности, работает на износ.`,origin:`Появился там, где уязвимость встречала осуждение или воспринималась как опасность.`,cost:`Истощает ресурсы тела и психики, лишает права на настоящую поддержку.`,need:`Право на уязвимость иногда, не теряя при этом уважения к себе.`,healthyAdult:`«Уязвимость — не слабость. Можно позволить себе устать и попросить о помощи»`},flagellating_oc:{about:`Наказывает себя за любую оплошность жёстче, чем того требует ситуация.`,triggers:`Собственная ошибка; промах; несовпадение с собственными завышенными ожиданиями.`,body:`Тяжесть, сжатие внутри, физическое ощущение вины после малейшего промаха.`,voice:`«Заслуживаю наказания за это»`,behavior:`Изнуряет себя работой, отказывает себе в отдыхе и удовольствии после ошибки.`,origin:`Сложился там, где наказание казалось единственным способом «исправиться».`,cost:`Наказание не предотвращает будущие ошибки, а только добавляет страдания к уже случившейся.`,need:`Опыт того, что к себе можно отнестись бережно даже после реальной ошибки.`,healthyAdult:`«Ошибаться — по-человечески. Отнесусь к себе так же бережно, как к близкому другу»`},compulsive_oc:{about:`Снижает тревогу через повторяющиеся ритуалы и проверки, которые приходится повторять снова.`,triggers:`Тревога без ясного источника; ощущение, что что-то может пойти не так.`,body:`Напряжение, которое отпускает лишь после ритуала, и снова нарастает.`,voice:`«Надо проверить ещё раз, иначе будет плохо»`,behavior:`Повторяет действия и проверки по кругу, не может остановиться на одном разе.`,origin:`Появился там, где ритуал однажды помог почувствовать хоть какой-то контроль над тревогой.`,cost:`Ритуал отнимает время и силы, а тревога возвращается почти сразу после облегчения.`,need:`Опыт того, что тревогу можно выдержать без ритуала, и она пройдёт сама.`,healthyAdult:`«Ритуал даёт лишь временное облегчение. Можно выдержать тревогу чуть дольше без него»`},worrying_oc:{about:`Прокручивает катастрофические сценарии снова и снова, пытаясь предугадать беду.`,triggers:`Неопределённое будущее; ситуация без ясного исхода; зона вне прямого влияния.`,body:`Напряжение в груди, сбивчивые мысли по кругу, трудно уснуть от прокрутки сценариев.`,voice:`«А что, если случится самое худшее»`,behavior:`Просчитывает катастрофы, ищет гарантии, многократно переспрашивает и перепроверяет.`,origin:`Сложился там, где бдительность и тревога когда-то помогали предугадать реальную опасность.`,cost:`Тревога растёт быстрее, чем реальная вероятность беды, а покой не наступает.`,need:`Опыт того, что не всё предсказуемо, и это можно выдержать без катастрофы.`,healthyAdult:`«Что самое реалистичное из возможного? Что можно сделать прямо сейчас, а не додумывать»`},bully_attack:{about:`Добивается своего через давление, угрозу и агрессию — нападение как лучшая защита.`,triggers:`Ощущение, что могут отказать, не послушаться или проявить неуважение.`,body:`Взвинченность, сжатые кулаки, готовность ответить силой на малейший вызов.`,voice:`«Будет по-моему, и точка»`,behavior:`Повышает голос, угрожает, давит, добиваясь подчинения силой.`,origin:`Появился там, где сила была единственным языком, который срабатывал.`,cost:`Разрушает доверие и отношения, оставляя после себя страх, а не уважение.`,need:`Опыт того, что о своём можно попросить прямо, не прибегая к угрозе.`,healthyAdult:`«За напором прячется страх не получить желаемое. Можно попросить прямо, без давления»`},manipulative:{about:`Добивается своего окольными путями, скрывая настоящие намерения за намёками и виной.`,triggers:`Ситуация, где прямая просьба кажется рискованной — вдруг откажут или осудят.`,body:`Внутреннее напряжение расчёта, лёгкая тревога при мысли сказать прямо.`,voice:`«Пусть сами догадаются, чего хочу»`,behavior:`Намекает, вызывает чувство вины, подстраивает ситуацию вместо прямой просьбы.`,origin:`Сложился там, где прямые просьбы игнорировались или наказывались.`,cost:`Подрывает доверие в отношениях — обман раскрывается, а близость от этого страдает.`,need:`Опыт того, что прямая просьба может быть услышана без обмана и манипуляции.`,healthyAdult:`«Можно попросить прямо о том, что нужно. Отказ — не катастрофа»`},predator:{about:`Использует людей как средство для своей цели, почти без доступа к сочувствию к ним.`,triggers:`Ситуация, где чужая уязвимость становится удобным способом получить желаемое.`,body:`Холодная сосредоточенность на цели, отсутствие эмоционального отклика на чужую боль.`,voice:`«Это просто средство для моей цели»`,behavior:`Использует, обманывает или причиняет вред другим ради собственной выгоды.`,origin:`Складывается как крайняя защита там, где сочувствие когда-то оказалось опасным.`,cost:`Разрушает связь с людьми и с собственной человечностью — сигнал для помощи специалиста.`,need:`Восстановление доступа к эмпатии — работа, которая делается вместе с терапевтом.`,healthyAdult:`«Другой человек — не средство. Это состояние — сигнал, с которым стоит идти к специалисту»`},attention_seeker:{about:`Постоянно ищет признания и похвалы, чтобы почувствовать собственную значимость.`,triggers:`Ситуация без внимания к себе; отсутствие отклика или похвалы от окружающих.`,body:`Беспокойство без отклика извне, лёгкость и подъём, когда замечают и хвалят.`,voice:`«Нужно, чтобы меня заметили и похвалили»`,behavior:`Ищет центр внимания, часто спрашивает мнение о себе, зависит от реакции окружающих.`,origin:`Появился там, где ценность признавалась только через внешнее одобрение, а не сама по себе.`,cost:`Собственная ценность держится на чужом мнении и рассыпается без постоянного отклика.`,need:`Опыт собственной ценности, не зависящей от того, заметили её сейчас или нет.`,healthyAdult:`«Моя ценность не исчезает без чужого одобрения. Можно опираться и на себя тоже»`},pollyanna:{about:`Отрицает трудности и видит всё в розовом цвете, лишь бы не встречаться с болью.`,triggers:`Реальная проблема, конфликт или боль, которую было бы тяжело признать.`,body:`Наигранная лёгкость, напряжение под улыбкой, избегание разговора о плохом.`,voice:`«Да всё нормально, не о чем беспокоиться»`,behavior:`Отшучивается, обесценивает чужие тревоги, меняет тему при разговоре о трудном.`,origin:`Сложился там, где признавать проблему было слишком опасно или бесполезно.`,cost:`Реальные трудности остаются нерешёнными, а близкие чувствуют себя неуслышанными.`,need:`Опыт того, что честно назвать трудность можно, не разрушив всё вокруг.`,healthyAdult:`«Можно назвать трудность как есть. Посмотреть честно — не значит всё разрушить»`}},l={demanding_critic:{about:`Внутренний голос завышенных стандартов — пока не идеально, отдыхать нельзя.`,triggers:`Завершённая задача; момент паузы; результат, недостаточно «идеальный».`,body:`Напряжение, вина при мысли об отдыхе, невозможность расслабиться.`,voice:`«Недостаточно стараюсь, надо больше»`,behavior:`Требует новых достижений, обесценивает сделанное, не даёт остановиться.`,origin:`Усвоенный голос значимого взрослого, для которого любовь была условием достижений.`,cost:`Отдых и радость от сделанного недоступны — планка каждый раз отодвигается выше.`,need:`Право на паузу и признание того, что уже сделано, без новых условий.`,healthyAdult:`«Сделанного уже достаточно. Планку можно отодвинуть и не подгонять себя новой»`},punitive_critic:{about:`Жёстко судит и наказывает за любую ошибку — будто снисхождения не полагается.`,triggers:`Собственная ошибка; промах; несовпадение с чужими ожиданиями.`,body:`Стыд, опустошение, физическое ощущение приговора внутри.`,voice:`«Опять всё испорчено, наказание заслужено»`,behavior:`Обвиняет, стыдит изнутри, лишает права на снисхождение к себе.`,origin:`Усвоенный голос значимого взрослого, который критиковал, стыдил или наказывал за ошибки.`,cost:`Оставляет после себя стыд и опустошение вместо урока и возможности исправиться.`,need:`Право ошибаться и быть человеком без внутреннего приговора за это.`,healthyAdult:`«Этот голос — не факт и не то, кто я на самом деле. Ошибаться — по-человечески, отнесусь к себе бережно»`},guilt_critic:{about:`Постоянно напоминает о долге перед другими и вызывает чувство вины без реальной причины.`,triggers:`Отказ кому-то; забота о себе вместо других; выбор между собой и чужими нуждами.`,body:`Тяжесть в груди, тревожное чувство долга, трудно радоваться собственному выбору.`,voice:`«У всех в долгу, всех подвожу»`,behavior:`Извиняется без повода, жертвует своим, испытывает вину за собственные границы.`,origin:`Усвоенный голос там, где забота о себе называлась эгоизмом.`,cost:`Собственные потребности систематически откладываются в пользу чужих, копится обида.`,need:`Право заботиться о себе без вины и признание, что не все долги — настоящие.`,healthyAdult:`«Вина — не всегда факт. Мои потребности имеют право быть, даже без разрешения»`}},u={happy_child:{about:`Спонтанная радость, лёгкость и игривость — без тревоги и необходимости соответствовать.`,triggers:`Игра; творчество; безопасное присутствие близких; момент без задач и оценки.`,body:`Лёгкость в теле, улыбка, желание двигаться, смеяться, пробовать новое.`,voice:`«Мне сейчас легко и хорошо, просто так»`,behavior:`Играет, шутит, пробует новое, радуется без повода и без оглядки на оценку.`,origin:`Питается безопасностью, принятием и моментами без давления и оценки.`,cost:`Тревога, спешка, ощущение, что несерьёзность будет осуждена.`,need:`Пространство и время для игры без цели и без оценки результата.`,healthyAdult:`«Можно порадоваться просто так, без повода и без чувства, что время тратится зря»`},healthy_adult:{about:`Взрослая часть, которая видит ситуацию целиком, заботится о себе и учитывает других.`,triggers:`Момент, требующий взвешенного решения, заботы о себе или спокойного разговора о границах.`,body:`Устойчивость, ровное дыхание, ясность вместо тумана или спешки.`,voice:`«Вижу ситуацию целиком, можно решить спокойно»`,behavior:`Ставит границы, заботится о потребностях, успокаивает уязвимые части внутри.`,origin:`Питается опытом успешной заботы о себе и накопленной практикой — растёт с каждым разом.`,cost:`Стресс, истощение и незамеченные потребности отодвигают его в сторону защитных режимов.`,need:`Регулярная практика заботы о себе — отдых, признание сделанного, поддержка со стороны.`,healthyAdult:`«Можно опираться на себя и заботиться о себе так же, как о близком человеке»`},good_parent:{about:`Внутренний тёплый голос поддержки, который ободряет и успокаивает вместо критики.`,triggers:`Момент неудачи, усталости или трудности, когда особенно нужна не критика, а тепло.`,body:`Тепло в груди, расслабленные плечи, ощущение, что можно выдохнуть и не защищаться.`,voice:`«Я рядом с собой, что бы ни случилось»`,behavior:`Успокаивает, подбадривает, признаёт усилия и не требует немедленного совершенства.`,origin:`Питается опытом настоящей заботы — своей или чужой — которую однажды удалось получить или дать себе.`,cost:`Усталость, спешка и усвоенная привычка критиковать раньше, чем поддержать.`,need:`Практика обращаться к себе с той же теплотой, что и к близкому человеку в трудности.`,healthyAdult:`«Отнесусь к себе с той же теплотой, что и к близкому другу»`}},d={...o,...s,...c,...l,...u};function f(e){return d[e]}export{a as n,f as t};